using namespace std;

const int MaxHolidays = 25;
const int MaxDescLength = 40;
const char HOLIDAY_FILE[] = "Holidays.txt";

struct holidayStruct {
    int holidayId;
    char description[MaxDescLength+1]; // add +1 for the terminal character \0
    int month;
    int day;
    double cost;
};

holidayStruct* readHoliday(FILE* holidayFile)
{
    int id;
    char n;                     //EOF flag
    holidayStruct *holidayPtr;

    n = fscanf(holidayFile, "%i", &id); //return how many things where read in.
    if (n != EOF) {
        holidayPtr = (holidayStruct*)malloc(sizeof(holidayStruct)); //By default the malloc is a (void pointer)
        if (!holidayFile) {
            perror("Critical Error: Failure to allocate memory in ");
            perror("readHoliday() function.\n");
            perror("Contact your holiday management program team to resolve\n");
            perror("this problem.\n");
            fflush(stdout); // Clears the output buffer
            exit(1); // Part of the c library
        }
        holidayPtr->holidayId = id;
        fscanf(holidayFile,"%i %i %lf", &holidayPtr->month, &holidayPtr->day, &holidayPtr->cost);
        //holidayFile.ignore();
        //holidayFile.getline(holidayPtr->description, MaxDescLength+1);
        fgets(holidayPtr->description, (MaxDescLength+1), holidayFile);
        return (holidayPtr);
    } else return NULL;
}

int main()
{
    holidayStruct* items[MaxHolidays]; //struct instance

    int i;               // general loop counter
    int itemCount;       // current number of items
    char n;              // used to check the EOF
    FILE* inputFile;

    inputFile = fopen(HOLIDAY_FILE, "r"); //opening a file | reading from file to memory
    if (!inputFile)
    {
        printf("Holiday file ");
        for (i = 0; i < strlen(HOLIDAY_FILE);i++)
            printf("%c", HOLIDAY_FILE[i]);
        printf(" could not be opened.\n");
        //cerr << "Holiday file " << HOLIDAY_FILE
        //     << " could not be opened." << endl;
        //cin.get();

        exit(1);
    }

    //reading from the file
    itemCount = 0;
    while (itemCount < MaxHolidays
        && (items[itemCount] = readHoliday(inputFile)) )
        ++itemCount;
    //cout << itemCount << " holidays read in.\n";
    printf("%d holidays read in.\n", itemCount);

    //cout << setiosflags(ios::fixed);
    //cout.precision(2);

    if (itemCount)
       // cout << setw(10) << "id" << setw(10) << "Month"
       //     << setw(10) << "Day" << setw(12) << "Cost"
       //     << "  Description\n\n";
