using namespace std;

int compute_stats(struct numlist *);

struct numlist {
    float *list;   /* points to list of numbers */
    int   len;     /* number of items in list   */
    float min,     /* the minimal value in list */
          max,     /* the maximal value in list */
          avg;     /* the mean of the numbers   */
};
int compute_stats(struct numlist *listptr)
{
    int result;
    if(listptr == NULL)
        {
            result = -1;
        }else if (listptr->list == NULL){
        result = -2;
        }else if (listptr ->len < 1){
        result = -3;
        }else {
        int storemin,storemax,sum=0;
                storemin = listptr ->list[0];
                storemax = listptr ->list[0];
        if(listptr ->len == 1){
                sum += listptr ->list[0];
                result=0;
        }else
        for(int i = 0;i<listptr->len;i++){
            if (listptr ->list[i] < listptr ->list[i+1]){
                storemin = listptr ->list[i];}
            if (listptr ->list[i] > listptr ->list[i+1]){
                storemax = listptr ->list[i];}
            sum += listptr ->list[i];
        }
                listptr ->min = storemin;
                listptr ->max = storemax;
                listptr ->avg = sum*(1.0)/listptr ->len;
                result = 0;

        }

 return result;

}

