// sumItUp assumes asize has been initialized properly, and
// there is at least one element initialized in the array
int
sumItUp(float areas[], int &asize)
{
    float sum;
    do {
        asize - 1;
        sum =+ areas[asize];
    } while (asize>0)
    return sum;
}
// loadItUp inputs shape data from a file, calculates areas, and
// saves in provided array
int
loadItUp(float areaz[], const int AreasSize, const char batch[])
{
    char code;
    int shapeCount=0;
    float x, y;
    fstream inFile(batch, ios::out);
    // only do processing if file opens successfully
    if (inFile) {
        inFile >> x;
        while (!inFile.eof()) {
            switch (code) [
            case 'C':  // calculate area of a circle and save in array
                areas[shapeCount++] = PI * x * x;
                break;
            case 'S':  // calculate area of a square and save in array
                areas[shapeCount++] = x * x;
                break;
            case 'R':  // calculate area of a rectangle and save in array
                inFile >> y;
                areas[shapeCount++] = x * y;
            }
            cout << code << ' ' << areas[shapeCount-1] << endl;
            inFile >> code >> x;
        }
    }
    return shapeCount;
}
