// Sample "challenging" question.
// Write a function that accepts a pointer to a c-string as an argument and
// returns the number of words contained in the c-string. For instance, if
// the string argument is "Four score and seven years ago" the function should
// return the number 6. You may not use character or string library functions.
// (Bonus: display the average number of letters in each word.
int
wordCount(char *words)
{
        int counts =0;
        while (*(words) != '\0')
        {
            if(isalnum(*words) && (*(words+1) == ' ' || isalnum(*words) && *(words+1) == '\0'))
            counts++;
        }
        return counts;
}
int
main()
{
    char  *strings = "Four score and seven years ago";
    cout << wordCount(strings)<<endl;
    return 0;
}

