#include <iostream>
using namespace std;
const int MaxSize = 10;
class container {
private:
    float list[MaxSize];
    int size;









public:   // Add your prototypes for constructor and member functions here
    container();
    int accessor();
    void mutator(double);
    double sumAccessor();
    double smallest();

    container()
    {
        size = 0;
    }
    int accessor()
    {

        return size;
    }
    void mutator(double addNum)
    {
      if ( > MaxSize  )
      {
          list[] += addNum;
      }

    }
    double sumAccessor()
    {
        double total =0.0;
        for (int i =0 ; i < MaxSize ; i++)
        {
            total += list[i];
        }
        return total;
    }
    double smallest()
    {
        double small = list[0];
        for(int i =0 ; i < MaxSize; i++)
        {
            if (list[i] < small)
                small = list[i];
        }
        return small;
    }

};

