const int maxLength = 101;

// Demonstrate that an array of character pointers to arrays works the same
// way as a 2 dimensional array of characters (almost)
int
main()
{
    char line1[maxLength], line2[maxLength], line3[maxLength];
    char *lines[]= {line1, line2, line3};
    char lineArray[3][maxLength];
    int i;
    int row, col;

    cout << "Enter three lines of text" << endl;
    for (i=0; i < 3; i++)
        cin.getline(lineArray[i], maxLength);

    cout << "Now enter three more lines" << endl;
    for (i=0; i < 3; i++)
        cin.getline(lines[i], maxLength);

    cout << "The first three lines:\n";
    for (i=0; i < 3; i++)
        cout << lineArray[i] << endl;

    cout << "The first four characters of the first three lines:\n";
    for (row=0; row < 3; row++) {
        for (col=0; col < 3; col++)
            cout << lineArray[row][col];
        cout << endl;
    }

    cout << "The second three lines:\n";
    for (i=0; i < 3; i++)
        cout << lines[i] << endl;

    cout << "The first four characters of the second three lines:\n";
    for (row=0; row < 3; row++) {
        for (col=0; col < 3; col++)
            cout << lines[row][col];
        cout << endl;
    }

    return(0);
}

